using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class WholeGroundingChecks {
 static string Ordinary(object body){var j=new JavaScriptSerializer();var req=SceneMaterial.Json(j.Serialize(body));var messages=(object[])CaptionService.Get(req,"messages");var input=SceneMaterial.Json((string)CaptionService.Get(messages.Last(),"content"));var words=(object[])CaptionService.Get(input,"words");return j.Serialize(new{word_kinds=words.Select(w=>new{id=(int)CaptionService.Get(w,"id"),kind="ordinary_expression"}).ToArray()});}
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
 public static int Main(){try{var json=new JavaScriptSerializer();var video=new Video{Id="V0000000001",Title="스킨 색상 구경"};var content=new VideoContent{Version=1,VideoId=video.Id,Language="ko",Source="YouTube 공개 자막",AcquiredAt=DateTime.UtcNow.ToString("o"),Cues=new List<CaptionCue>{new CaptionCue{Text="분홍색도 예쁘고 초록색도 예쁘네요."}}};var evidence=new[]{new KeyValuePair<string,CaptionCue>("c0",content.Cues[0])};string comment="스킨 색상이 예쁘네요. 다만 플레이가 더 흥미로웠으면 좋겠어요.";
 Check(WholeCommentGrounding.Clauses(comment).Length==2,"positive sentence and later criticism both receive program-owned coverage");Check(WholeCommentGrounding.Clauses("예쁜데요ㅋㅋ, 하지만 좀 더 가벼웠으면 좋겠어요").Length==2,"comma and contrast conjunction do not lose the second clause");
 Check(WholeCommentGrounding.Clauses("와, 핑크색이 정말 예쁘네요!").Length==1,"exclamation prefix remains attached to the actual reaction instead of requiring separate factual proof");
 string good=json.Serialize(new{supported=true,context_clear=true,added_claim=false,asserts_event_result=false,source_kind="no_event",comment_outcome="none",context_outcome="undetermined",source=0,quote="분홍색도 예쁘고 초록색도 예쁘네요."});Check(WholeCommentGrounding.Parse(good,"고르는 데 고민되겠네요",video,evidence).Supported,"viewer choice reaction may use evidence without copying its words");
 Check(!WholeCommentGrounding.Parse(json.Serialize(new{supported=true,context_clear=true,added_claim=false,asserts_event_result=false,source_kind="no_event",comment_outcome="none",context_outcome="undetermined",source=0,quote="원문에 없는 근거"}),"반응",video,evidence).Reason.Contains("원문에 없는 근거"),"model cannot replace program-owned original evidence with its own quotation");Check(!WholeCommentGrounding.Parse(json.Serialize(new{supported=true,context_clear=true,added_claim=false,asserts_event_result=false,source_kind="no_event",comment_outcome="none",context_outcome="undetermined",source=99,quote="분홍색"}),"반응",video,evidence).Supported,"nonexistent source cannot satisfy a positive model verdict");
 using(var model=new LocalModel("unused")){int checks=0;Func<object,CancellationToken,Task<string>> chat=(body,t)=>{var req=SceneMaterial.Json(json.Serialize(body));var props=CaptionService.Get(CaptionService.Get(req,"format"),"properties");var messages=(object[])CaptionService.Get(req,"messages");var input=SceneMaterial.Json((string)CaptionService.Get(messages.Last(),"content"));if(CaptionService.Get(props,"references")!=null)return Task.FromResult("{\"references\":[]}");if(CaptionService.Get(props,"source")!=null){checks++;string part=(string)CaptionService.Get(input,"candidate_comment");return Task.FromResult(json.Serialize(new{evaluated_comment=part,supported=!part.Contains("흥미"),context_clear=true,added_claim=part.Contains("흥미"),asserts_event_result=false,source_kind="no_event",comment_outcome="none",context_outcome="undetermined",source=0,quote=part.Contains("흥미")?"":"분홍색도 예쁘고 초록색도 예쁘네요."}));}if(CaptionService.Get(props,"voices")!=null)return Task.FromResult("{\"voices\":[{\"id\":0,\"voice\":\"viewer\"}]}");return Task.FromResult("{\"connection\":\"specific_reaction\",\"evidence\":0}");};
 var result=new WholeCommentGrounding(model,chat).Assess(video,evidence,comment,CancellationToken.None).GetAwaiter().GetResult();Check(checks==2&&!result.Supported&&result.Reason.Contains("다만 플레이"),"later unsupported wish vetoes the whole comment and appears in the explanation");
 var scores=new SceneFitScoring(model,chat).Assess(video,content,new[]{new CommentSuggestion{Text=comment}},CancellationToken.None).GetAwaiter().GetResult();Check(!scores[0].Eligible&&scores[0].Score==0,"maximum relevance and grammar scores cannot override one unsupported clause");
 }return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
